<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { CalendarClock, Plus } from 'lucide-vue-next'
import { routineLayout, timeMinutes, type RoutineEntry } from '../../shared/domain'
const props=defineProps<{entries:RoutineEntry[];enabled:boolean;today:string;busy:boolean}>()
const emit=defineEmits<{toggle:[value:boolean];edit:[entry?:RoutineEntry]}>()
const weekdayOf=(date:string)=>new Date(`${date}T12:00:00Z`).getUTCDay()
const selected=ref(weekdayOf(props.today))
watch(()=>props.today,(value,old)=>{if(selected.value===weekdayOf(old))selected.value=weekdayOf(value)})
const weekdays=[{id:1,label:'월'},{id:2,label:'화'},{id:3,label:'수'},{id:4,label:'목'},{id:5,label:'금'},{id:6,label:'토'},{id:0,label:'일'}]
const firstHour=computed(()=>Math.min(8,...props.entries.map(entry=>Math.floor(timeMinutes(entry.start_time)/60))))
const lastHour=computed(()=>Math.max(20,...props.entries.map(entry=>Math.ceil(timeMinutes(entry.end_time)/60))))
const hours=computed(()=>Array.from({length:lastHour.value-firstHour.value},(_,i)=>firstHour.value+i))
const rowHeight=64
const height=computed(()=>hours.value.length*rowHeight)
const layout=(day:number)=>routineLayout(props.entries,day)
function blockStyle(block:ReturnType<typeof routineLayout>[number]){
 return {top:((timeMinutes(block.entry.start_time)-firstHour.value*60)*rowHeight/60)+'px',height:((timeMinutes(block.entry.end_time)-timeMinutes(block.entry.start_time))*rowHeight/60)+'px',left:`calc(${block.lane*100/block.lanes}% + 3px)`,width:`calc(${100/block.lanes}% - 6px)`}
}
</script>
<template>
  <section class="routine-panel panel" aria-label="고정 시간표">
    <div class="routine-heading"><div><h2><CalendarClock :size="21" />고정 시간표 <span>선택</span></h2><p>매주 반복하는 루틴을 요일과 시간에 맞춰 확인하세요.</p></div><button class="routine-switch" role="switch" :aria-checked="enabled" aria-label="홈에 고정 시간표 표시" :disabled="busy" @click="emit('toggle',!enabled)"><span></span></button></div>
    <template v-if="enabled">
      <div class="routine-toolbar"><div class="routine-weekdays" role="group" aria-label="루틴 요일 선택"><button v-for="day in weekdays" :key="day.id" :aria-pressed="selected===day.id" @click="selected=day.id">{{ day.label }}</button></div><span class="routine-desktop-note">매주 반복되는 시간표</span><button class="outline-button" @click="emit('edit')"><Plus :size="16" />루틴 추가</button></div>
      <div class="timetable-scroll" role="region" aria-label="주간 고정 시간표" tabindex="0"><div class="timetable-header"><span class="time-axis-title">시간</span><button v-for="day in weekdays" :key="day.id" class="timetable-day-title" :class="{'is-selected':selected===day.id,istoday:weekdayOf(today)===day.id}" @click="selected=day.id">{{ day.label }}요일<span v-if="weekdayOf(today)===day.id">오늘</span></button></div><div class="timetable-body" :style="{height:height+'px'}"><div class="timetable-time-axis"><span v-for="hour in hours" :key="hour" :style="{top:(hour-firstHour)*rowHeight+'px'}">{{ String(hour).padStart(2,'0') }}:00</span></div><div v-for="day in weekdays" :key="day.id" class="timetable-day-column" :class="{'is-selected':selected===day.id,istoday:weekdayOf(today)===day.id}" :aria-label="day.label+'요일 루틴'"><span v-for="hour in hours" :key="hour" class="timetable-rule" :style="{top:(hour-firstHour)*rowHeight+'px',height:rowHeight+'px'}"></span><button v-for="block in layout(day.id)" :key="block.entry.id" class="routine-block" :class="{compact:timeMinutes(block.entry.end_time)-timeMinutes(block.entry.start_time)<30}" :style="blockStyle(block)" :title="block.entry.title+' '+block.entry.start_time+'–'+block.entry.end_time" :aria-label="day.label+'요일 '+block.entry.start_time+'부터 '+block.entry.end_time+' '+block.entry.title+' 수정'" @click="emit('edit',block.entry)"><strong>{{ block.entry.title }}</strong><span>{{ block.entry.start_time }}–{{ block.entry.end_time }}</span></button></div></div></div>
      <p v-if="!entries.length" class="routine-empty">루틴을 추가하면 시간표에 표시됩니다.</p><p class="routine-note">블록을 누르면 수정할 수 있습니다. 날짜별 할 일과 별도로 관리합니다.</p>
    </template>
  </section>
</template>
<style scoped>
.routine-panel{margin-bottom:30px}.routine-heading{display:flex;justify-content:space-between;align-items:center;gap:18px}.routine-heading h2{display:flex;align-items:center;gap:9px}.routine-heading h2>span{font-size:11px;color:#9aa88e;border:1px solid #e0e7d9;border-radius:5px;padding:2px 5px;letter-spacing:0}.routine-heading p{font-size:14px;color:#87967b;margin-top:9px;line-height:1.8}.routine-switch{width:42px;height:24px;border-radius:99px;background:#dfe5da;padding:3px;flex-shrink:0}.routine-switch span{width:18px;height:18px;border-radius:50%;background:white;display:block;box-shadow:0 1px 3px #0001;transition:transform .15s}.routine-switch[aria-checked=true]{background:var(--brand)}.routine-switch[aria-checked=true] span{transform:translateX(18px)}.routine-toolbar{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:25px 0 17px}.routine-weekdays{display:none;gap:7px}.routine-weekdays button{width:37px;height:37px;border-radius:50%;font-size:14px;color:#8a987f;background:#f2f5ee}.routine-weekdays button[aria-pressed=true]{background:var(--brand);color:white;font-weight:700}.routine-toolbar .outline-button{font-size:13px;min-height:37px}.routine-desktop-note{font-size:13px;color:#97a48c}.timetable-scroll{max-height:450px;overflow:auto;border:1px solid #e1e7dc;border-radius:11px;scrollbar-width:thin;overscroll-behavior:contain}.timetable-header,.timetable-body{display:grid;grid-template-columns:58px repeat(7,minmax(0,1fr))}.timetable-header{position:sticky;top:0;background:#fbfcf8;z-index:4;border-bottom:1px solid #e3e9de;min-height:47px}.time-axis-title{display:grid;place-items:center;color:#a3ad98;font-size:12px}.timetable-day-title{font-size:14px;color:#829275;border-left:1px solid #e8ede3;padding:12px 3px;display:flex;justify-content:center;align-items:center;gap:6px;flex-wrap:wrap}.timetable-day-title.istoday{color:var(--green);font-weight:700;background:#f0f7eb}.timetable-day-title>span{font-size:10px;font-weight:500;background:#e0efd7;border-radius:4px;padding:2px 4px}.timetable-time-axis{position:relative;background:#fbfcf9}.timetable-time-axis>span{position:absolute;right:7px;font-size:11px;color:#9ba88f;transform:translateY(6px)}.timetable-day-column{position:relative;border-left:1px solid #e7ecdf;min-width:0}.timetable-day-column.istoday{background:#f9fcf5}.timetable-rule{position:absolute;left:0;right:0;border-bottom:1px solid #e6ecdf;pointer-events:none}.timetable-rule:after{content:'';position:absolute;left:0;right:0;top:50%;border-top:1px dashed #f0f3eb}.routine-block{position:absolute;z-index:1;display:flex;flex-direction:column;gap:4px;align-items:flex-start;padding:5px 7px;border-radius:5px;text-align:left;background:#e3f0dc;border-left:3px solid #84af71;color:#507243;overflow:hidden;min-width:0}.routine-block strong{font-size:13px;font-weight:700;line-height:1.5;overflow-wrap:anywhere}.routine-block>span{font-size:11px;color:#7c9c6b;white-space:nowrap}.routine-block.compact{padding-top:2px;padding-bottom:0;gap:0}.routine-block.compact>span{display:none}.routine-empty{font-size:13px;color:#9ba78f;text-align:center;padding:20px}.routine-note{font-size:12px;color:#a0ad95;margin-top:16px;line-height:1.8}
@media(max-width:767px){.routine-heading{align-items:flex-start}.routine-heading h2{font-size:17px}.routine-heading p{font-size:13px}.routine-toolbar{flex-wrap:wrap}.routine-weekdays{display:flex;gap:5px}.routine-weekdays button{width:33px;height:33px}.routine-toolbar .outline-button{margin-left:auto}.routine-desktop-note{display:none}.timetable-header,.timetable-body{grid-template-columns:52px minmax(0,1fr)}.timetable-day-title,.timetable-day-column{display:none}.timetable-day-title.is-selected{display:flex}.timetable-day-column.is-selected{display:block}.routine-block strong{font-size:14px}.routine-block>span{font-size:12px}.timetable-scroll{max-height:410px}}
